-- -- INSERT INTO tmp_drill_data VALUES('Advance','ad8903ec-e765-4f0e-a6a2-359337f37b82',12,16,TRUE,'Three-point shot','Wheel up from corner to wing 3 pt distance. Step 1: Start on the baseline corner three point line Step 2: the player will run with the ball a couple steps above the three point line. Step 3:  The player will toss the ball in front of him or her, receiving the ball somewhere around the wing 3 point line set your feet and shoot',16,TRUE,9999,300,20);
-- -- INSERT INTO tmp_drill_data VALUES('Advance','ad8903ec-e765-4f0e-a6a2-359337f37b82',12,17,TRUE,'Three-point shot','3pt Fade Cut: Step 1: the player will start above the three-point line on the wing with the ball in his or her hands Step 2: the player will toss the ball towards the corner 3-point line sprinting towards the ball setting their feet and shooting a corner three',16,TRUE,9999,300,20);
-- -- INSERT INTO tmp_drill_data VALUES('Advance','ad8903ec-e765-4f0e-a6a2-359337f37b82',12,18,TRUE,'Three-point shot - Mid-range shot','Change distance cut shooting: player can you use two chairs and two basketballs or no chairs and two basketballs. If you do not have a chair players can set the ball on the ground at the appropriate location. Step 1: One ball at the right elbow, the other ball top of the key 3pt line. Step 2: the player will start directly under the hoop and cut straight up to the top of the key and shoot a three-point shot, make sure to follow your shot rebound it put it back at the top of the key. Step 3: after placing the ball on the ground at the top of the key the player will immediately cut back to the rim and cut straight to the right elbow for the second shot. This is a time drill you need to make 10 shots within 2 minutes.',16,TRUE,9999,120,20);
-- -- INSERT INTO tmp_drill_data VALUES('Advance','ad8903ec-e765-4f0e-a6a2-359337f37b82',12,19,TRUE,'Three-point shot - Mid-range shot','Change distance cut shooting (same drill as drill eight, but now Place the ball on the left elbow, instead of the right elbow): player can you use two chairs and two basketballs or no chairs and two basketballs. If you do not have a chair players can set the ball on the ground at the appropriate location. Step 1: One ball at the Left elbow, the other ball top of the key 3pt line. Step 2: the player will start directly under the hoop and cut straight up to the top of the key and shoot a three-point shot, make sure to follow your shot rebound it put it back at the top of the key. Step 3: after placing the ball on the ground at the top of the key the player will immediately cut back to the rim and cut straight to the right elbow for the second shot. This is a time drill you need to make 10 shots within 2 minutes.',16,TRUE,9999,120,20);
