-- -- INSERT INTO tmp_drill_data VALUES('Advance','ad8903ec-e765-4f0e-a6a2-359337f37b82',13,1,FALSE,'Three-point shot - Mid-range shot',replace('Starting in the RIGHT corner, sprint up the 3-point line to the wing with a ball in your hand, throw out the ball in front of you to the wing.\n1. first shot, catch and shoot. \n2. second shot, once you catch the pass do a shot fake then rip and attack the baseline two dribbles pull-up..\n3. third shot, shot fake, rip and attack the baseline with one dribble, then step back to shoot.','\n',CHR(10)),16,TRUE,9999,'180',20);
-- -- INSERT INTO tmp_drill_data VALUES('Advance','ad8903ec-e765-4f0e-a6a2-359337f37b82',13,2,FALSE,'Three-point shot - Mid-range shot',replace('Starting in the LEFT corner, sprint up the 3-point line to the wing with a ball in your hand, throw out the ball in front of you to the wing.\n1. first shot, catch and shoot. \n2. second shot, once you catch the pass do a shot fake then rip and attack the baseline two dribbles pull-up..\n3. third shot, shot fake, rip and attack the baseline with one dribble, then step back to shoot.','\n',CHR(10)),16,TRUE,9999,'180',20);
-- -- INSERT INTO tmp_drill_data VALUES('Advance','ad8903ec-e765-4f0e-a6a2-359337f37b82',13,3,FALSE,'Three-point shot - Mid-range shot','Starting in the RIGHT corner, sprint up the 3-point line to the wing with a ball in your hand, throw out the ball in front of you to the wing. Now execute the following 3 moves 1. curl to elbow lead step, step back. 2. curl to elbow, into cross-step retreat dribble to 3 point line then shoot. 3. curl to elbow, into one retreat dribble, then attack downhill through legs, into step-back',16,TRUE,9999,'180',20);
