-- -- INSERT INTO tmp_drill_data VALUES('Beginner','aac04c9c-b71a-47af-8cc2-861ce4cd5acd',11,8,FALSE,'Three-point shot - Mid-range shot','Change distance cut shooting: player can you use two chairs and two basketballs or no chairs and two basketballs. If you do not have a chair players can set the ball on the ground at the appropriate location. Step 1: One ball at the right elbow, the other ball top of the key 3pt line. Step 2: the player will start directly under the hoop and cut straight up to the top of the key and shoot a three-point shot, make sure to follow your shot rebound it put it back at the top of the key. Step 3: after placing the ball on the ground at the top of the key the player will immediately cut back to the rim and cut straight to the right elbow for the second shot. This is a time drill you need to make 10 shots within 2 minutes.',10,TRUE,9999,120,20);
