-- -- INSERT INTO tmp_drill_data VALUES('Beginner','aac04c9c-b71a-47af-8cc2-861ce4cd5acd',12,20,TRUE,'Free-throw shot','Free throw routine',17,TRUE,9999,300,20);
-- -- INSERT INTO tmp_drill_data VALUES('Beginner','aac04c9c-b71a-47af-8cc2-861ce4cd5acd',13,1,FALSE,'Three-point shot - Mid-range shot',replace('Starting in the RIGHT corner, sprint up the 3-point line to the wing with a ball in your hand, throw out the ball in front of you to the wing.\n1. first shot, catch and shoot. \n2. second shot, once you catch the pass do a shot fake then rip and attack the baseline two dribbles pull-up..\n3. third shot, shot fake, rip and attack the baseline with one dribble, then step back to shoot.','\n',CHR(10)),12,TRUE,9999,300,20);
-- -- INSERT INTO tmp_drill_data VALUES('Beginner','aac04c9c-b71a-47af-8cc2-861ce4cd5acd',13,2,FALSE,'Three-point shot - Mid-range shot',replace('Starting in the LEFT corner, sprint up the 3-point line to the wing with a ball in your hand, throw out the ball in front of you to the wing.\n1. first shot, catch and shoot. \n2. second shot, once you catch the pass do a shot fake then rip and attack the baseline two dribbles pull-up..\n3. third shot, shot fake, rip and attack the baseline with one dribble, then step back to shoot.','\n',CHR(10)),12,TRUE,9999,300,20);
-- -- INSERT INTO tmp_drill_data VALUES('Beginner','aac04c9c-b71a-47af-8cc2-861ce4cd5acd',13,3,FALSE,'Three-point shot - Mid-range shot','Starting in the RIGHT corner, sprint up the 3-point line to the wing with a ball in your hand, throw out the ball in front of you to the wing. Now execute the following 3 moves 1. curl to elbow lead step, step back. 2. curl to elbow, into cross-step retreat dribble to 3 point line then shoot. 3. curl to elbow, into one retreat dribble, then attack downhill through legs, into step-back',12,TRUE,9999,300,20);
