-- -- INSERT INTO tmp_drill_data VALUES('Intermediate','6ccc50a3-f356-416e-98db-ed50e58e976b',13,1,FALSE,'Three-point shot - Mid-range shot',replace('Starting in the RIGHT corner, sprint up the 3-point line to the wing with a ball in your hand, throw out the ball in front of you to the wing.\n1. first shot, catch and shoot. \n2. second shot, once you catch the pass do a shot fake then rip and attack the baseline two dribbles pull-up..\n3. third shot, shot fake, rip and attack the baseline with one dribble, then step back to shoot.','\n',CHR(10)),13,TRUE,9999,'180',20);
