-- -- INSERT INTO tmp_drill_data VALUES('Intermediate','6ccc50a3-f356-416e-98db-ed50e58e976b',13,5,FALSE,'Three-point shot - Mid-range shot','Starting in the RIGHT WING, sprint to the CORNER with a ball in your hand, throw out the ball in front of for a CORNER 3 pt line. Now execute the following 3 moves 1. catch and shoot from the corner 2. shot fake 3-point shot one dribble baseline pull up 3. Shot fake three-point shot foot fake baseline cross step drive middle two dribbles step back shot',13,TRUE,9999,'180',20);
